custom_css:
@import url('https://fonts.googleapis.com/css2?family=Roboto+Mono:ital,wght@1,400;1,700&display=swap');

body, * {
    font-family: "Roboto Mono", monospace !important;
    font-style: italic !important;
}

html {
    background-color: #000000 !important;
}

body {
    background-color: transparent !important;
}

#root, .window-frame {
    background-color: transparent !important;
}

/* Layering fix */
#root { position: relative; }
.app-layout { position: relative; }
.sidebar, .main-content, .header-bar {
    position: relative;
    z-index: 1;
}

html::before, html::after, body::before, body::after,
#root::before, #root::after, .app-layout::before, .app-layout::after,
.window-frame::before {
    will-change: transform;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    transform: translateZ(0);
}

/* 3D Spikes (Optimized for low lag) */
#root::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 600px;
    height: 600px;
    margin-top: -300px;
    margin-left: -300px;
    background: repeating-conic-gradient(from 0deg, transparent 0deg, rgba(255,255,255,0.3) 2deg, transparent 4deg, transparent 45deg);
    border-radius: 50%;
    z-index: 0;
    pointer-events: none;
    animation: spikeRotate 30s steps(30) infinite;
}

@keyframes spikeRotate {
    0%   { transform: perspective(800px) rotateX(60deg) rotateY(20deg) rotateZ(0deg); }
    100% { transform: perspective(800px) rotateX(60deg) rotateY(20deg) rotateZ(360deg); }
}

/* Checkerboard Floor */
.window-frame::before {
    content: '';
    position: absolute;
    bottom: -30vh;
    left: -20vw;
    width: 140vw;
    height: 70vh;
    background-image: 
        linear-gradient(45deg, #0303EB 25%, transparent 25%, transparent 75%, #0303EB 75%, #0303EB),
        linear-gradient(45deg, #0303EB 25%, transparent 25%, transparent 75%, #0303EB 75%, #0303EB);
    background-color: #D3DDF4;
    background-size: 100px 100px;
    background-position: 0 0, 50px 50px;
    transform: perspective(400px) rotateX(70deg);
    transform-origin: center center;
    z-index: 0;
    pointer-events: none;
    mask-image: radial-gradient(ellipse at center, black 0%, black 40%, transparent 80%);
    -webkit-mask-image: radial-gradient(ellipse at center, black 0%, black 40%, transparent 80%);
    animation: floorMove 2s steps(8, end) infinite;
}

@keyframes floorMove {
    0% { background-position: 0 0, 50px 50px; }
    100% { background-position: 0 100px, 50px 150px; }
}

/* Ring 1 */
.app-layout::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 800px;
    height: 800px;
    margin-top: -400px;
    margin-left: -400px;
    border: 15px solid rgba(0, 34, 255, 0.8);
    border-radius: 50%;
    box-shadow: 0 0 20px rgba(0, 34, 255, 1);
    animation: ringRotate 15s steps(20, end) infinite, ringCorrupt 6s steps(1) infinite;
    z-index: 0;
    pointer-events: none;
}

@keyframes ringRotate {
    0%   { transform: perspective(800px) rotateX(60deg) rotateY(20deg) rotateZ(0deg); }
    25%  { transform: perspective(800px) rotateX(75deg) rotateY(10deg) rotateZ(90deg); }
    50%  { transform: perspective(800px) rotateX(60deg) rotateY(-20deg) rotateZ(180deg); }
    75%  { transform: perspective(800px) rotateX(45deg) rotateY(-10deg) rotateZ(270deg); }
    100% { transform: perspective(800px) rotateX(60deg) rotateY(20deg) rotateZ(360deg); }
}

/* Ring 2 */
.app-layout::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 600px;
    height: 600px;
    margin-top: -300px;
    margin-left: -300px;
    border: 5px solid rgba(255, 255, 255, 0.4);
    border-radius: 50%;
    animation: ringRotateReverse 10s steps(15, end) infinite, ringCorrupt 5s steps(1) infinite;
    z-index: 0;
    pointer-events: none;
}

@keyframes ringRotateReverse {
    0%   { transform: perspective(800px) rotateX(60deg) rotateY(-20deg) rotateZ(0deg); }
    25%  { transform: perspective(800px) rotateX(45deg) rotateY(-30deg) rotateZ(-90deg); }
    50%  { transform: perspective(800px) rotateX(60deg) rotateY(10deg) rotateZ(-180deg); }
    75%  { transform: perspective(800px) rotateX(75deg) rotateY(0deg) rotateZ(-270deg); }
    100% { transform: perspective(800px) rotateX(60deg) rotateY(-20deg) rotateZ(-360deg); }
}

@keyframes ringCorrupt {
    0%   { border-color: rgba(0, 34, 255, 0.8); }
    80%  { border-color: rgba(0, 34, 255, 0.8); }
    83%  { border-color: rgba(255, 255, 255, 0.9); }
    86%  { border-color: rgba(0, 34, 255, 0.8); }
    89%  { border-color: rgba(0, 255, 255, 0.9); }
    92%  { border-color: rgba(0, 34, 255, 0.8); }
    100% { border-color: rgba(0, 34, 255, 0.8); }
}

/* Ring 3 */
.corner-bracket.tl::before {
    content: '';
    position: absolute;
    top: 300px;
    left: 400px;
    width: 1000px;
    height: 1000px;
    margin-top: -500px;
    margin-left: -500px;
    border: 2px solid rgba(255, 255, 255, 0.2);
    border-radius: 50%;
    will-change: transform;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    animation: ringRotate 20s steps(25, end) infinite reverse, ringCorrupt 4s steps(1) infinite;
    z-index: 0;
    pointer-events: none;
}

/* Command Prompt */
#root::after {
    content: '';
    white-space: pre-wrap;
    position: absolute;
    top: 15%;
    right: 15%;
    width: 280px;
    height: 120px;
    background: rgba(0, 0, 30, 0.8);
    background-image: linear-gradient(#0022ff 25px, transparent 25px);
    border: 2px solid #0022ff;
    color: #ffffff;
    font-size: 13px;
    font-family: 'Courier New', Courier, monospace !important;
    font-style: normal !important;
    padding: 35px 15px 15px 15px;
    box-shadow: 10px 10px 0px rgba(0, 34, 255, 0.3);
    z-index: 0;
    pointer-events: none;
    animation: popupFloat 7s ease-in-out infinite, glitchFlash 5s steps(1) infinite, cmdTyping 8s steps(1) infinite;
}

@keyframes cmdTyping {
    0%  { content: 'C:\\> _'; }
    10% { content: 'C:\\> e'; }
    15% { content: 'C:\\> ex'; }
    20% { content: 'C:\\> exe'; }
    25% { content: 'C:\\> exec'; }
    30% { content: 'C:\\> exec _'; }
    35% { content: 'C:\\> exec p'; }
    40% { content: 'C:\\> exec pr'; }
    45% { content: 'C:\\> exec pro'; }
    50% { content: 'C:\\> exec proto                                          ERROR: Protocol corrupted.'; }
    70% { content: 'C:\\> exec proto                                          ERROR: Protocol corrupted.                                Rebooting...'; }
    90% { content: 'C:\\> exec proto                                          ERROR: Protocol corrupted.                                Rebooting...                              [OK]'; }
    100%{ content: 'C:\\> _'; }
}

@keyframes popupFloat {
    0%, 100% { transform: perspective(600px) rotateY(-20deg) rotateX(10deg) translateY(0px); }
    50% { transform: perspective(600px) rotateY(-15deg) rotateX(5deg) translateY(-20px); }
}

@keyframes glitchFlash {
    0%  { opacity: 0.9; background-color: rgba(0, 0, 30, 0.8); color: #fff; }
    90% { opacity: 0.9; }
    92% { opacity: 0.2; background-color: rgba(255, 255, 255, 0.8); color: #000; }
    94% { opacity: 1; background-color: rgba(0, 0, 30, 0.8); color: #fff; }
    96% { opacity: 0.4; background-color: rgba(0, 255, 255, 0.3); }
    98% { opacity: 0.9; background-color: rgba(0, 0, 30, 0.8); }
}

body::before {
    content: 'you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet you are a puppet';
    position: absolute;
    top: 25%;
    left: 10%;
    width: 250px;
    height: 350px;
    background: rgba(0, 0, 255, 0.9);
    border: 3px solid #0022ff;
    box-shadow: -10px 10px 0px rgba(0, 34, 255, 0.3);
    color: rgba(255, 255, 255, 0.8);
    font-size: 22px;
    font-family: 'Times New Roman', Times, serif !important;
    font-style: normal !important;
    line-height: 1.1;
    text-align: center;
    white-space: pre-wrap;
    overflow: hidden;
    z-index: 1;
    pointer-events: none;
    transform: perspective(600px) rotateY(15deg) rotateX(10deg);
    animation: popupFloatLeft 8s ease-in-out infinite, smileyFlash 4s steps(1) infinite;
}

/* Smiley Face Icon */
body::after {
    content: '☺';
    position: absolute;
    top: 25%;
    left: 10%;
    width: 250px;
    height: 350px;
    color: #ffffff;
    font-size: 180px;
    font-family: 'Courier New', Courier, monospace !important;
    font-style: normal !important;
    display: flex;
    align-items: center;
    justify-content: center;
    text-shadow: 0 0 20px #ffffff;
    z-index: 2;
    pointer-events: none;
    transform: perspective(600px) rotateY(15deg) rotateX(10deg);
    animation: popupFloatLeft 8s ease-in-out infinite, smileyFlash 4s steps(1) infinite;
}

@keyframes popupFloatLeft {
    0%, 100% { transform: perspective(600px) rotateY(15deg) rotateX(10deg) translateY(0px); }
    50% { transform: perspective(600px) rotateY(10deg) rotateX(5deg) translateY(-20px); }
}

@keyframes smileyFlash {
    0%, 100% { opacity: 1; }
    88% { opacity: 1; }
    90% { opacity: 0.3; }
    95% { opacity: 0.8; }
}

html::after {
    content: '';
    position: absolute;
    bottom: 28%;
    left: 26%;
    width: 250px;
    height: 2px;
    background: #ffffff;
    box-shadow: 0 0 5px #0022ff;
    z-index: 0;
    pointer-events: none;
    animation: lineFloat 6s ease-in-out infinite;
}

@keyframes lineFloat {
    0%, 100% { transform: rotate(-35deg) translateY(0px); }
    50% { transform: rotate(-30deg) translateY(-10px); }
}

/* Japanese Text */
html::before {
    content: 'ドリームステート';
    position: absolute;
    bottom: 15%;
    right: 10%;
    color: rgba(255, 255, 255, 0.7);
    text-shadow: 0 0 10px #0022ff;
    font-size: 26px;
    letter-spacing: 6px;
    font-style: normal !important;
    z-index: 0;
    pointer-events: none;
    animation: textFloat 9s ease-in-out infinite, jpFlash 3s steps(1) infinite;
}

@keyframes textFloat {
    0%, 100% { transform: perspective(600px) rotateY(-20deg) translateY(0px) scale(1); }
    50% { transform: perspective(600px) rotateY(-10deg) translateY(-20px) scale(1.05); }
}

@keyframes jpFlash {
    0%, 100% { color: rgba(255, 255, 255, 0.7); text-shadow: 0 0 10px #0022ff; }
    50% { color: #0022ff; text-shadow: 0 0 20px #ffffff; }
}

/* CRT Scanlines */
.window-frame::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: linear-gradient(
      to bottom,
      rgba(255,255,255,0),
      rgba(255,255,255,0) 50%,
      rgba(0,0,0,0.2) 50%,
      rgba(0,0,0,0.2)
    );
    background-size: 100% 4px;
    pointer-events: none;
    z-index: 9996;
}

/* ===== TITLE & VERSION ===== */
.sidebar-brand h1 {
    background: none !important;
}

.title-letter {
    display: inline-block;
    color: #ffffff;
    -webkit-text-fill-color: #ffffff;
    text-shadow: none;
    animation: letterShake 1.5s steps(1, end) infinite, titleFlash 0.8s steps(1, end) infinite;
}
.title-letter:nth-child(even) { animation-duration: 1.2s, 0.9s; animation-direction: reverse, normal; }
.title-letter:nth-child(3n) { animation-duration: 1.8s, 0.7s; }
.title-letter:nth-child(5n) { animation-duration: 2.1s, 1.1s; animation-delay: 0.3s, 0.1s; }

@keyframes letterShake {
    0%   { transform: translateX(0px); }
    10%  { transform: translateX(-3px); }
    20%  { transform: translateX(2px); }
    30%  { transform: translateX(0px); }
    40%  { transform: translateX(3px); }
    50%  { transform: translateX(-2px); }
    60%  { transform: translateX(0px); }
    70%  { transform: translateX(3px); }
    80%  { transform: translateX(-3px); }
    90%  { transform: translateX(2px); }
    100% { transform: translateX(0px); }
}

@keyframes titleFlash {
    0%   { color: #ffffff; -webkit-text-fill-color: #ffffff; opacity: 1; }
    50%  { color: #0022ff; -webkit-text-fill-color: #0022ff; opacity: 0.5; }
    100% { color: #ffffff; -webkit-text-fill-color: #ffffff; opacity: 1; }
}

.version-letter {
    display: inline-block;
    color: #ffffff;
    -webkit-text-fill-color: #ffffff;
    text-shadow: none;
    animation: titleFlash 0.6s steps(1, end) infinite;
}
.version-letter:nth-child(even) { animation-delay: 0.1s; animation-duration: 0.7s; }
.version-letter:nth-child(odd) { animation-delay: 0.2s; animation-duration: 0.5s; }

/* Censor Block */
.sidebar-item.active {
    position: relative;
}

.sidebar-item.active::after {
    content: 'DO';
    position: absolute;
    left: 45px;
    right: 15px;
    top: 50%;
    margin-top: -10px;
    height: 20px;
    background: #ffffff;
    border: 1px solid #0022ff;
    color: #0022ff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
    font-weight: 900;
    font-style: normal !important;
    font-family: 'Courier New', Courier, monospace !important;
    z-index: 9999;
    pointer-events: none;
    will-change: transform, opacity;
    animation: sidebarCensorText 3.5s steps(1) infinite;
}

@keyframes sidebarCensorText {
    0%   { content: 'D0'; transform: translateX(0) scaleY(1); opacity: 1; }
    20%  { content: 'NO!'; transform: translateX(-2px) scaleY(1.1); opacity: 1; }
    40%  { content: 'W@KE#$'; transform: translateX(2px) scaleY(0.9); opacity: 1; }
    60%  { content: 'THEM'; transform: translateX(-4px) scaleY(1.05); opacity: 1; }
    80%  { content: '??UP??'; transform: translateX(3px) scaleY(0.95); opacity: 1; }
    100% { content: 'DO'; transform: translateX(0) scaleY(1); opacity: 1; }
}

